list_pages.code:
const response = await client.pages.listPages({search: 'about', visibility: 'open', sort: 'name', order: 'asc'});
for (const page of response.map.pages) {
    console.log(page.id, page.name, page.url, page.visibility, page.active, page.landing);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

create_page.code:
const response = await client.pages.createPage({
    page: {
        name: 'About us',
        title: 'About us',
        visibility: 'open',
        layout: {id: 28},
    },
});
console.log(response.map.page.id, response.map.page.url, response.map.page.full_url);
console.log(response.headers.location);

get_page.code:
const response = await client.pages.getPage(812);
const page = response.map.page;
console.log(page.name, page.title, page.url, page.visibility, page.layout?.name, page.in_trash);
console.log(response.headers.etag);

update_page.code:
const response = await client.pages.updatePage(812, {
    page: {
        name: 'About us', title: 'About us', subtitle: 'Who we are', url: 'about-us',
        layout: {id: 28}, visibility: 'open', body_class: 'about-page',
        active: true, disable_tracking: false, password_protection: {enabled: false},
    },
});
const page = response.map.page;
console.log(page.subtitle, page.body_class, page.updated_at, response.headers.etag);

